/// Prefix of the model metadata fallback warning, up to the model slug.
const MODEL_METADATA_WARNING_PREFIX: &str = "Model metadata for `";
/// Suffix of the model metadata fallback warning, following the model slug.
const MODEL_METADATA_WARNING_SUFFIX: &str =
    "` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.";

/// Tracks which warnings have already been displayed so that repeated,
/// model-specific metadata warnings can be deduplicated in the chat history.
#[derive(Default)]
pub(super) struct WarningDisplayState {
    /// Model slugs for which a metadata fallback warning has already been shown.
    seen_model_metadata_slugs: HashSet<String>,
}

impl WarningDisplayState {
    /// Returns whether `message` should be added to the chat history.
    ///
    /// For model metadata fallback warnings, this returns `true` the first time
    /// a given slug is encountered and `false` for every subsequent occurrence
    /// of the same slug. All other warnings always return `true`.
    pub(super) fn should_display(&mut self, message: &str) -> bool {
        match extract_model_metadata_slug(message) {
            Some(slug) => self.seen_model_metadata_slugs.insert(slug.to_string()),
            None => true,
        }
    }
}

/// Extracts the model slug from a metadata fallback warning, if `message`
/// matches the exact pattern used to emit those warnings.
fn extract_model_metadata_slug(message: &str) -> Option<&str> {
    message
        .strip_prefix(MODEL_METADATA_WARNING_PREFIX)?
        .strip_suffix(MODEL_METADATA_WARNING_SUFFIX)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn model_metadata_warning(slug: &str) -> String {
        format!(
            "Model metadata for `{slug}` not found. Defaulting to fallback metadata; this can degrade performance and cause issues."
        )
    }

    #[test]
    fn model_metadata_warning_is_deduplicated_per_slug() {
        let mut state = WarningDisplayState::default();
        let warning = model_metadata_warning("unknown-model");

        assert!(state.should_display(&warning));
        assert!(!state.should_display(&warning));
        assert!(!state.should_display(&warning));

        // A different slug is displayed once on its own.
        let other = model_metadata_warning("another-model");
        assert!(state.should_display(&other));
        assert!(!state.should_display(&other));
    }

    #[test]
    fn generic_warnings_are_always_displayed() {
        let mut state = WarningDisplayState::default();
        let warning = "Something generic happened.";

        assert!(state.should_display(warning));
        assert!(state.should_display(warning));
        assert!(state.should_display(warning));
    }

    #[test]
    fn extracts_slug_from_metadata_warning() {
        assert_eq!(
            extract_model_metadata_slug(&model_metadata_warning("gpt-x")),
            Some("gpt-x")
        );
        assert_eq!(extract_model_metadata_slug("unrelated warning"), None);
    }
}
